// The parity table's two renderings: the whole of it, cell by cell, as
// testdata/golden/parity.golden, and its summary in the page,
// docs/engine/parity-dns.md, between its markers. make golden-update
// (pkg/ui/uitest's -update) rewrites both.

const parityHeader = `# The DNS parity table: origin/main's DNS path against the DNS control and screen
# (refactor plan §2, slice 2's unit (b2), next/s2-parity; docs/engine/parity-dns.md).
# Generated by TestParity (pkg/screens/dns); make golden-update rewrites it. Do not edit.
# origin/main: pkg/characterization's goldens, read in place. The new path: hardn -g's plan
# and apply through the engine (the screen's Configure DNS leaves the same) and the screen's
# items, on hostfake with the screen tests' resolver model: written, not run (gate 5).
# Probes (commands that only read) are recorded, not compared.
# Sources: V<n> side-effects.md §8; decision <n> gallery-dns.md §4 (adopted 2026-10-22);
# P-37 (a) proposals.md; plan §3.19 (as amended 2026-10-22); side-effects row 29 (§3);
# screen-dns.md §2.8.
`

// renderCells is the golden: every cell, both paths' end states, what
// agrees and what differs, each difference with its source.
func renderCells(cells []parityCell) string {
	want, _ := expand()
	var b strings.Builder
	b.WriteString(parityHeader)
	for _, c := range cells {
		fmt.Fprintf(&b, "\n== %s on %s\n", c.sc.name, c.d.label)
		fmt.Fprintf(&b, "host: %s (%s)\n", c.state, c.shipped)
		fmt.Fprintf(&b, "origin/main: %s (%s)\n", c.legacy.golden, strings.Join(c.legacy.vs, ", "))
		writeState(&b, c.legacy.live)
		if c.legacy.cli != "" {
			fmt.Fprintf(&b, "  hardn -n: refused, %s\n", c.legacy.cli)
		}
		if !c.compared {
			fmt.Fprintf(&b, "not compared: %s\n", c.why)
			continue
		}
		if c.sc.lines == nil {
			b.WriteString("new path: hardn -g's plan and apply; the screen's Configure DNS leaves the same\n")
		} else {
			fmt.Fprintf(&b, "new path: the DNS screen, typed %s\n", strings.Join(answers(c, c.sc.lines), ", "))
		}
		writeState(&b, c.live)
		for _, a := range c.agree {
			fmt.Fprintf(&b, "agree  %s: %s\n", a.name, a.legacy)
		}
		for _, d := range c.diffs {
			fmt.Fprintf(&b, "differ %s: %s | %s\n", d.name, d.legacy, d.new)
			if e, ok := want[key{c.sc.name, c.d.name, d.name}]; ok {
				fmt.Fprintf(&b, "       %s: %s\n", e.source, e.why)
			} else {
				b.WriteString("       UNEXPLAINED\n")
			}
		}
		fmt.Fprintf(&b, "v0.3.2: %s\n", c.sc.v032)
	}
	return b.String()
}

// writeState is s, indented: the probes, each file written with its
// content (hardn.yml as its lines changed against the fixture, or its
// size when written whole), the directories, the commands, and what the
// new path adds.
func writeState(b *strings.Builder, s endState) {
	if len(s.probes) > 0 {
		fmt.Fprintf(b, "  probes: %s\n", strings.Join(s.probes, "; "))
	}
	if s.refusal != "" {
		fmt.Fprintf(b, "  refused: %s\n", s.refusal)
	}
	for _, f := range s.files {
		fmt.Fprintf(b, "  write %s, %s\n", f, method(endState{files: []fileWrite{f}}))
		for _, l := range f.lines {
			b.WriteString(strings.TrimRight("    | "+l, " ") + "\n")
		}
	}
	if s.yml != nil {
		fmt.Fprintf(b, "  write %s %04o, %s: %s\n", s.yml.path, uint32(s.yml.mode), method(endState{yml: s.yml}), rest(*s.yml, s.loaded))
		if s.yml.path != "./hardn.yml" { // origin/main's whole file is in its own golden
			for _, l := range lineDiff(s.loaded, s.yml.lines) {
				fmt.Fprintf(b, "    %s\n", l)
			}
		}
	}
	for _, d := range s.dirs {
		if strings.HasPrefix(d, "chmod ") {
			fmt.Fprintf(b, "  %s\n", d)
		} else {
			fmt.Fprintf(b, "  mkdir %s\n", d)
		}
	}
	for _, a := range s.actions {
		fmt.Fprintf(b, "  run %s\n", a)
	}
	if s.journal || len(s.backups) > 0 || len(s.findings) > 0 {
		fmt.Fprintf(b, "  backup: %s; journal: %s; findings: %s\n", joined(s.backups), journal(s), joined(s.findings))
	}
}

// lineDiff is the lines of was that are not in now ("-"), then the lines
// of now that are not in was ("+"), each in its order: a saved hardn.yml
// against the file loaded.
func lineDiff(was, now []string) []string {
	var out []string
	for _, l := range was {
		if !slices.Contains(now, l) {
			out = append(out, "- "+l)
		}
	}
	for _, l := range now {
		if !slices.Contains(was, l) {
			out = append(out, "+ "+l)
		}
	}
	return out
}

func distrosOf(e tie) []string {
	if e.distros != nil {
		return e.distros
	}
	var out []string
	for _, d := range parityDistros {
		out = append(out, d.name)
	}
	return out
}

// renderPage is the page's summary: the host states, every difference
// grouped where both paths' values and the source agree, and v0.3.2.
func renderPage(cells []parityCell) string {
	var b strings.Builder
	b.WriteString("<!-- TestParity: begin. Generated by TestParity (pkg/screens/dns); make golden-update rewrites it. Do not edit. -->\n\n")
	b.WriteString("**Host states** (§3): what the new path ran on, and whether the distribution's stock install has it.\n\n")
	b.WriteString("| Scenario |")
	for _, d := range parityDistros {
		b.WriteString(" " + d.label + " |")
	}
	b.WriteString("\n|---|---|---|---|---|\n")
	for _, sc := range parityScenarios {
		if sc.lines != nil {
			continue
		}
		fmt.Fprintf(&b, "| %s |", sc.name)
		for _, c := range cells {
			if c.sc.name == sc.name {
				word, _, _ := strings.Cut(c.shipped, ":")
				fmt.Fprintf(&b, " %s (%s) |", short(c.state), word)
			}
		}
		b.WriteString("\n")
	}
	b.WriteString("\nThe menu's items ran on each distribution's stock install.\n\n")

	b.WriteString("**Agreeing and differing aspects** (§4): in how many compared cells each aspect agrees and differs.\n\n")
	b.WriteString("| Aspect | Agrees in | Differs in |\n|---|---|---|\n")
	var aspects []string
	count := map[string][2]int{}
	for _, c := range cells {
		for i, as := range [][]aspect{c.agree, c.diffs} {
			for _, a := range as {
				if _, ok := count[a.name]; !ok {
					aspects = append(aspects, a.name)
				}
				n := count[a.name]
				n[i]++
				count[a.name] = n
			}
		}
	}
	for _, a := range aspects {
		fmt.Fprintf(&b, "| %s | %d | %d |\n", a, count[a][0], count[a][1])
	}
	b.WriteString("\n**Differences** (§4): each with its source; every cell, both end states whole, is in [parity.golden](../../pkg/screens/dns/testdata/golden/parity.golden).\n\n")
	b.WriteString("| Scenarios | On | Aspect | origin/main | New path | Source |\n|---|---|---|---|---|---|\n")
	type group struct {
		a     aspect
		e     tie
		cells [][2]string // scenario, distribution
	}
	var groups []*group
	want, _ := expand()
	for _, c := range cells {
		for _, d := range c.diffs {
			e, ok := want[key{c.sc.name, c.d.name, d.name}]
			if !ok {
				e = tie{source: "UNEXPLAINED"}
			}
			i := slices.IndexFunc(groups, func(g *group) bool { return g.a == d && g.e.source == e.source && g.e.why == e.why })
			if i < 0 {
				groups = append(groups, &group{a: d, e: e})
				i = len(groups) - 1
			}
			groups[i].cells = append(groups[i].cells, [2]string{c.sc.name, c.d.name})
		}
	}
	for _, g := range groups {
		scenarios, on := where(g.cells)
		fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %s: %s |\n", scenarios, on, g.a.name, cell(g.a.legacy), cell(g.a.new), g.e.source, g.e.why)
	}

	b.WriteString("\n**v0.3.2** (§4): where it differs from origin/main, from [v032-reference.md](../refactor/phase0/v032-reference.md) §4.5, §5.1, §6.\n\n")
	b.WriteString("| Scenarios | v0.3.2 |\n|---|---|\n")
	var done []string
	for _, sc := range parityScenarios {
		if slices.Contains(done, sc.v032) {
			continue
		}
		done = append(done, sc.v032)
		var names []string
		for _, o := range parityScenarios {
			if o.v032 == sc.v032 {
				names = append(names, o.name)
			}
		}
		fmt.Fprintf(&b, "| %s | %s |\n", strings.Join(names, ", "), sc.v032)
	}
	b.WriteString("\n<!-- TestParity: end -->\n")
	return b.String()
}

// short is a host state in a word or two, for the page's table.
func short(state string) string {
	return map[string]string{stateFile: "a file", stateResolved: "resolved's stub", stateResolvconf: "resolvconf's link"}[state]
}

// cell is a value for a Markdown table cell.
func cell(s string) string { return "`" + strings.ReplaceAll(s, "|", `\|`) + "`" }

// where is a group's cells as the table's first two columns: its
// scenarios, and the distributions they share, or each scenario's own.
func where(cells [][2]string) (scenarios, on string) {
	by := map[string][]string{}
	var order []string
	for _, c := range cells {
		if _, ok := by[c[0]]; !ok {
			order = append(order, c[0])
		}
		by[c[0]] = append(by[c[0]], c[1])
	}
	label := func(ds []string) string {
		if len(ds) == len(parityDistros) {
			return "all"
		}
		return strings.Join(ds, ", ")
	}
	same := true
	for _, s := range order {
		same = same && slices.Equal(by[s], by[order[0]])
	}
	if same {
		return strings.Join(order, ", "), label(by[order[0]])
	}
	var parts []string
	for _, s := range order {
		parts = append(parts, s+" ("+label(by[s])+")")
	}
	return strings.Join(parts, "; "), "as listed"
}

// updating reports whether the test runs with -update (pkg/ui/uitest's
// flag, which make golden-update passes).
func updating() bool {
	f := flag.Lookup("update")
	return f != nil && f.Value.String() == "true"
}

// golden compares got with testdata/<name>, or rewrites it under -update.
func golden(t *testing.T, name string, got []byte) {
	t.Helper()
	p := filepath.Join("testdata", name)
	if updating() {
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, got, 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	want, err := os.ReadFile(p)
	if err != nil {
		t.Fatalf("%v (run make golden-update to create it)", err)
	}
	if !bytes.Equal(want, got) {
		t.Errorf("%s does not match; if the change is intended, run make golden-update and give the reason in the review description.\n--- got\n%s", p, got)
	}
}

// parityPage is the page whose summary region the test writes.
var parityPage = filepath.Join("..", "..", "..", "docs", "engine", "parity-dns.md")

// page compares region with the page's, between its markers, or rewrites
// it there under -update.
func page(t *testing.T, region string) {
	t.Helper()
	data, err := os.ReadFile(parityPage)
	if err != nil {
		t.Fatal(err)
	}
	s := string(data)
	const begin, end = "<!-- TestParity: begin", "<!-- TestParity: end -->\n"
	i, j := strings.Index(s, begin), strings.Index(s, end)
	if i < 0 || j < i {
		t.Fatalf("%s has no region between %q and %q", parityPage, begin, end)
	}
	if s[i:j+len(end)] == region {
		return
	}
	if !updating() {
		t.Fatalf("%s's table is not the one TestParity makes; run make golden-update.\n--- got\n%s", parityPage, region)
	}
	if err := os.WriteFile(parityPage, []byte(s[:i]+region+s[j+len(end):]), 0o644); err != nil {
		t.Fatal(err)
	}
}
